# Customize the schema and validation for this standalone archive.
ARCHIVE_KIND = 'expenses'
ARCHIVE_FIELDS = [('date', 'Date (YYYY-MM-DD)', 'line', True, 10, []), ('category', 'Category', 'line', True, 80, []), ('description', 'Description', 'line', False, 200, []), ('amount', 'Amount (0.01-999999999.99)', 'line', True, 16, []), ('currency', 'Currency', 'choice', True, 3, ['EUR', 'USD', 'GBP']), ('direction', 'Direction', 'choice', True, 10, ['Expense', 'Income'])]

# Decimal arithmetic keeps monetary totals exact within each currency.
import datetime
from decimal import Decimal


def expense_amount(value):
    if re.fullmatch(r"[0-9]{1,9}([.,][0-9]{1,2})?", value) is None:
        raise ValueError("Use a positive amount with at most two decimals")
    amount = Decimal(value.replace(",", "."))
    if amount <= 0:
        raise ValueError("Amounts must be greater than zero")
    return amount


def archive_extra_validate(records):
    for record in records:
        if datetime.date.fromisoformat(record["date"]).isoformat() != record["date"]:
            raise ValueError("Dates must use YYYY-MM-DD")
        record["amount"] = format(expense_amount(record["amount"]), ".2f")


def archive_sort_key(record):
    return (record["date"], record["category"].casefold())


def archive_row_label(record):
    sign = "-" if record["direction"] == "Expense" else "+"
    return record["date"] + " " + sign + record["amount"] + " " + record["currency"] + " " + record["category"][:25]


def expense_totals(records):
    totals = {currency: Decimal("0.00") for currency in ("EUR", "USD", "GBP")}
    for record in records:
        amount = expense_amount(record["amount"])
        totals[record["currency"]] += amount if record["direction"] == "Income" else -amount
    return totals


# Generic archive helpers are embedded in each standalone starter.
import json
import os
import re
import tempfile
import uuid
from pathlib import Path


def archive_validate_records(records):
    # Validate every record before changing the visible collection.
    if not isinstance(records, list) or len(records) > 500:
        raise ValueError("Use a list of up to 500 records")
    result, identities = [], set()
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get("id"), str) or not 1 <= len(record["id"]) <= 80 or record["id"] in identities:
            raise ValueError("Records need unique nonempty IDs")
        clean = {"id": record["id"]}
        identities.add(record["id"])
        for key, label, kind, required, limit, choices in ARCHIVE_FIELDS:
            value = record.get(key)
            if not isinstance(value, str) or len(value) > limit or (required and not value.strip()):
                raise ValueError("Invalid field: " + label)
            value = value.strip()
            if choices and value not in choices:
                raise ValueError("Choose a valid " + label)
            clean[key] = value
        result.append(clean)
    archive_extra_validate(result)
    return sorted(result, key=archive_sort_key)


def archive_render(app):
    query = app.FilterEntry.get().casefold().strip()
    app.RecordList.delete(0, "end")
    app.archive_visible = []
    for record in app.archive_records:
        if query and not any(query in record[key].casefold() for key, *_ in ARCHIVE_FIELDS):
            continue
        app.archive_visible.append(record["id"])
        app.RecordList.insert("end", archive_row_label(record))
    if app.archive_selected not in app.archive_visible:
        app.archive_selected = None
    elif app.archive_selected is not None:
        app.RecordList.selection_set(app.archive_visible.index(app.archive_selected))
    app.StatusLabel.configure(text=f"{len(app.archive_visible)} shown / {len(app.archive_records)} records | Save JSON manually to keep changes")


def archive_clear(app):
    # Clear the editor without deleting any stored record.
    app.archive_selected = None
    app.RecordList.selection_clear(0, "end")
    for index, (key, label, kind, required, limit, choices) in enumerate(ARCHIVE_FIELDS):
        field = getattr(app, "Field" + str(index))
        if kind == "text":
            field.delete("1.0", "end")
        elif kind == "choice":
            field.set(choices[0])
        else:
            field.delete(0, "end")
    app.StatusLabel.configure(text="New record: fill the fields and press Add")


def archive_select(app):
    selection = app.RecordList.curselection()
    if not selection or selection[0] >= len(app.archive_visible):
        return
    identity = app.archive_visible[selection[0]]
    record = next((r for r in app.archive_records if r["id"] == identity), None)
    if record is None:
        return
    app.archive_selected = identity
    for index, (key, label, kind, required, limit, choices) in enumerate(ARCHIVE_FIELDS):
        field = getattr(app, "Field" + str(index))
        if kind == "text":
            field.delete("1.0", "end")
            field.insert("1.0", record[key])
        elif kind == "choice":
            field.set(record[key])
        else:
            field.delete(0, "end")
            field.insert(0, record[key])


def archive_collect(app, identity):
    record = {"id": identity}
    for index, (key, label, kind, required, limit, choices) in enumerate(ARCHIVE_FIELDS):
        field = getattr(app, "Field" + str(index))
        record[key] = field.get("1.0", "end-1c") if kind == "text" else field.get()
    return record


def archive_store(app, update=False):
    # Validate a copy so invalid edits never partially replace the collection.
    if update and app.archive_selected is None:
        messagebox.showinfo("Update record", "Select a record first", parent=app.Form1)
        return
    identity = app.archive_selected if update else uuid.uuid4().hex
    candidate = [r.copy() for r in app.archive_records if not update or r["id"] != identity]
    candidate.append(archive_collect(app, identity))
    try:
        candidate = archive_validate_records(candidate)
    except ValueError as error:
        messagebox.showerror("Invalid record", str(error), parent=app.Form1)
        return
    app.archive_records = candidate
    app.archive_selected = identity
    app.FilterEntry.delete(0, "end")
    archive_render(app)


def archive_delete(app):
    if app.archive_selected is not None and messagebox.askyesno("Delete record", "Delete the selected record?", parent=app.Form1):
        app.archive_records = [r for r in app.archive_records if r["id"] != app.archive_selected]
        archive_clear(app)
        archive_render(app)


def archive_save(app):
    filename = filedialog.asksaveasfilename(parent=app.Form1, defaultextension=".json", filetypes=[("Archive JSON", "*.json")])
    if not filename:
        return
    temporary = None
    try:
        path = Path(filename)
        content = json.dumps({"version": 1, "kind": ARCHIVE_KIND, "records": archive_validate_records(app.archive_records)}, ensure_ascii=False, indent=2)
        if len(content.encode("utf-8")) > 2 * 1024 * 1024:
            raise ValueError("Archive exceeds 2 MiB; reduce the collection before saving")
        descriptor, temporary = tempfile.mkstemp(dir=path.parent, prefix=".archive-", suffix=".tmp")
        with os.fdopen(descriptor, "w", encoding="utf-8") as stream:
            stream.write(content)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
        app.StatusLabel.configure(text="Saved: " + str(path))
    except (OSError, ValueError, UnicodeError) as error:
        messagebox.showerror("Save archive", str(error), parent=app.Form1)
    finally:
        if temporary is not None:
            Path(temporary).unlink(missing_ok=True)


def archive_open(app):
    filename = filedialog.askopenfilename(parent=app.Form1, filetypes=[("Archive JSON", "*.json")])
    if not filename:
        return
    try:
        path = Path(filename)
        if path.stat().st_size > 2 * 1024 * 1024:
            raise ValueError("Files are limited to 2 MiB")
        data = json.loads(path.read_text(encoding="utf-8-sig"))
        if not isinstance(data, dict) or data.get("version") != 1 or data.get("kind") != ARCHIVE_KIND:
            raise ValueError("This file belongs to another archive type or version")
        records = archive_validate_records(data.get("records"))
    except (OSError, ValueError, UnicodeError) as error:
        messagebox.showerror("Open archive", str(error), parent=app.Form1)
        return
    if messagebox.askyesno("Open archive", "Replace the collection? Save current changes first if needed.", parent=app.Form1):
        app.archive_records = records
        archive_clear(app)
        archive_render(app)


def archive_close(app):
    # There is no autosave: confirm before discarding the in-memory collection.
    if messagebox.askyesno("Close archive", "Close without saving? Use Save JSON first to keep changes.", parent=app.Form1):
        app.root.destroy()


# Totals always describe the entire collection, not just filtered rows.
_expense_render_base = archive_render

def archive_render(app):
    _expense_render_base(app)
    totals = expense_totals(app.archive_records)
    app.SummaryLabel.configure(text="All-record balances: " + " | ".join(currency + " " + format(amount, ".2f") for currency, amount in totals.items()))
